from pathlib import Path
src='''def transform(grid):
    h,w=len(grid),len(grid[0]); a=[r[:] for r in grid]
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
        if a[r][c] and (r,c) not in seen:
          col=a[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
          while q:
            x,y=q.pop(); cells.append((x,y))
            for dx in (-1,0,1):
              for dy in (-1,0,1):
                z=(x+dx,y+dy)
                if 0<=z[0]<h and 0<=z[1]<w and z not in seen and a[z[0]][z[1]]==col:
                  seen.add(z); q.append(z)
          objs.append((cells,col))
    # drop each object downward, lower objects first
    objs.sort(key=lambda o:max(x for x,y in o[0]), reverse=True)
    for cells,col in objs:
      for x,y in cells:a[x][y]=0
      while True:
        if any(x+1>=h or a[x+1][y]!=0 for x,y in cells):break
        cells=[(x+1,y) for x,y in cells]
      for x,y in cells:a[x][y]=col
    return a
'''
